def resolve(path, cwd, links):
    if links is None:
        links = {}

    if not path.startswith('/'):
        path = cwd + '/' + path

    components = path.split('/')
    current = []
    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        if comp == '' or comp == '.':
            i += 1
            continue

        if comp == '..':
            if current:
                current.pop()
            i += 1
            continue

        current.append(comp)
        current_path = '/' + '/'.join(current)

        if current_path in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current_path]

            if target.startswith('/'):
                current = []
                target_components = target.split('/')
            else:
                if current:
                    current.pop()
                current_path_dir = '/' + '/'.join(current) if current else '/'
                target_components = (current_path_dir + '/' + target).split('/')
                if current_path_dir == '/':
                    target_components = target.split('/')
                else:
                    target_components = (current_path_dir.rstrip('/') + '/' + target).split('/')
                current = []

            remaining_components = components[i + 1:]
            components = target_components + remaining_components
            i = 0
            continue

        i += 1

    if not current:
        return '/'

    return '/' + '/'.join(current)

